import{_ as t,o as i,c as o,a2 as a}from"./chunks/framework.Buc7gXeZ.js";const h=JSON.parse('{"title":"الاختبارات","description":"","frontmatter":{},"headers":[],"relativePath":"ar/permissions/testing.md","filePath":"ar/permissions/testing.md"}'),r={name:"ar/permissions/testing.md"};function n(s,e,l,c,d,p){return i(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="الاختبارات" tabindex="-1">الاختبارات <a class="header-anchor" href="#الاختبارات" aria-label="Permalink to &quot;الاختبارات&quot;">​</a></h1><p>٣٦ اختبار Pest عبر ٤ ملفات، كلهم ناجحين. الصفحة دي بتربط كل ادعاء متثبت بمكان إثباته — استخدمها عشان تلاقي الملف الصح قبل ما تضيف سيناريو جديد، وخليها صادقة: صف هنا بلا اختبار مطابق هو ادعاء مش حقيقة.</p><h2 id="tests-feature-organization-organizationscopetest-php-١٣-اختبار" tabindex="-1"><code>tests/Feature/Organization/OrganizationScopeTest.php</code> (١٣ اختبار) <a class="header-anchor" href="#tests-feature-organization-organizationscopetest-php-١٣-اختبار" aria-label="Permalink to &quot;`tests/Feature/Organization/OrganizationScopeTest.php` (١٣ اختبار)&quot;">​</a></h2><p>محرك نطاق البيانات، <code>entity_scope</code> × <code>department_scope</code> كتقاطع:</p><ul><li><code>entity_tree</code> بيشوف الكيان وكل التابعين له.</li><li><code>entity</code> (شركة واحدة) مش بيشوف الكيان الأب.</li><li><code>branch</code> على فرع مش رئيسي محصور بالفرع ده بس، مش الكيان كله.</li><li><code>department_tree</code> بيشوف الإدارة وإداراتها الفرعية.</li><li>مدير شركة تابعة مش بياخد نطاق على الأم، <strong>حتى لو بيشارك نفس صف الإدارة</strong> — الاختبار اللي بيثبت إن العزل جاي من بُعد الكيان، مش من صف إدارة منفصل لكل شركة.</li><li><code>own</code> على البُعدين بيرفض الرؤية لأي سجل تاني.</li><li>موظف منتهي الخدمة بيفقد الرؤية فورًا، مش عند أول دخول جاي.</li><li>مستخدم بلا سطر موظف نشط مش بيشوف حاجة (رفض كامل).</li><li><code>super_admin</code> بيتخطى النطاق كامل، حتى بلا أي سطر موظف خاص بيه (حالة قفل الإقلاع).</li><li><code>status = suspended</code> بيرفض النطاق بالظبط زي <code>terminated</code>.</li><li>موظف <code>entity_tree</code> كيانه اتمسح بالحذف الناعم بيرفض كل حاجة بدل ما ينهار (بيتحقق إن <code>-&gt;entity</code> مش null قبل ما ينادي <code>-&gt;descendantsAndSelf()</code>).</li><li>إعادة تعيين موظف منتهي الخدمة بترجّع الرؤية في نفس الاستعلام الجاي.</li></ul><h2 id="cache-invalidation" tabindex="-1"><code>tests/Feature/Organization/OrganizationVersionCacheTest.php</code> (٤ اختبارات) <a class="header-anchor" href="#cache-invalidation" aria-label="Permalink to &quot;`tests/Feature/Organization/OrganizationVersionCacheTest.php` (٤ اختبارات) {#cache-invalidation}&quot;">​</a></h2><ul><li>كاش النطاق بيبقى قديم في نفس لحظة تغيّر الشجرة — بلا تسجيل خروج/دخول، بلا مسح كاش يدوي.</li><li>زيادة العدّاد مرة بتلغي كاش كل المستخدمين في نفس اللحظة، مش بس اللي عمل الكتابة.</li><li>القراءات من غير كتابة بينهم بتفضل تستخدم نفس مفتاح الكاش (<code>rememberForever</code> مش بيتزود عدّاده بالصدفة مع كل قراءة).</li><li>نطاق مخزّن كرفض كامل (بلا سطر موظف) بيتلغى بتغيّر الشجرة زي أي نطاق تاني — موظف اتعيّن فورًا بعد التغيير ده مش هيفضل عالق على رفض كامل.</li></ul><h2 id="tests-feature-organization-employeepermissionsynchronizertest-php-٨-اختبارات" tabindex="-1"><code>tests/Feature/Organization/EmployeePermissionSynchronizerTest.php</code> (٨ اختبارات) <a class="header-anchor" href="#tests-feature-organization-employeepermissionsynchronizertest-php-٨-اختبارات" aria-label="Permalink to &quot;`tests/Feature/Organization/EmployeePermissionSynchronizerTest.php` (٨ اختبارات)&quot;">​</a></h2><p>محرك الصلاحيات الوظيفية وجداول منحه:</p><ul><li>منحة على مستوى اللقب بتسري على كل الدرجات الحاملة له.</li><li>منحة محددة بدرجة محجوبة تحت الحد، وبتتفتح لما يوصلها.</li><li>منحة على مستوى الإدارة بتوصل لكل حد فيها بغض النظر عن لقبه.</li><li>حد برّه الإدارة مش بياخد صلاحية موديولها.</li><li>دور مسمّى متلصق بلقب بيتحط تلقائيًا على أي حد حامله.</li><li>إنهاء خدمة موظف بيسحب صلاحياته وأدواره فورًا.</li><li><code>hr:permissions:reconcile</code> بيمسك ويصلّح انحراف من منحة اتضافت مباشرة على جدول منح، متخطّية المزامن.</li></ul><h2 id="tests-feature-organization-functionalpermissionscopetest-php-٤-اختبارات" tabindex="-1"><code>tests/Feature/Organization/FunctionalPermissionScopeTest.php</code> (٤ اختبارات) <a class="header-anchor" href="#tests-feature-organization-functionalpermissionscopetest-php-٤-اختبارات" aria-label="Permalink to &quot;`tests/Feature/Organization/FunctionalPermissionScopeTest.php` (٤ اختبارات)&quot;">​</a></h2><p>السيناريو ٦ — الصلاحيات الوظيفية ونطاق البيانات محورين مستقلين:</p><ul><li>مستخدم بنطاق بيانات أقصى (<code>entity_tree</code> + <code>department_tree</code>) لسه بيترفض من صلاحية بلا منحة — الرتبة التنظيمية ملهاش علاقة بالصلاحيات الوظيفية.</li><li>موديول بلا منحة غايب من شجرة التنقّل كامل، مش بس محجوب عند الراوت.</li><li>منح إدارة صلاحية بيقلب <code>can()</code> بلا أي لمسة لسطر الموظف خالص.</li><li>منحة صلاحية بس (بلا تغيير دور) لسه بتلغي كاش شجرة التنقّل — اختبار الرجوع لباج الكاش الموصوف في <a href="./functional-permissions#employeepermissionsynchronizer">functional-permissions.md</a>.</li></ul><h2 id="tests-feature-hr-organizationstructurescreenstest-php-٧-اختبارات" tabindex="-1"><code>tests/Feature/HR/OrganizationStructureScreensTest.php</code> (٧ اختبارات) <a class="header-anchor" href="#tests-feature-hr-organizationstructurescreenstest-php-٧-اختبارات" aria-label="Permalink to &quot;`tests/Feature/HR/OrganizationStructureScreensTest.php` (٧ اختبارات)&quot;">​</a></h2><p>تغطية دخان تثبت إن الشاشات الفعلية بترندر، مش بس المحرك اللي وراها:</p><ul><li>صفحات القوائم والعرض بترجّع <code>200</code> لكل من الكيانات، الفروع، الإدارات، الدرجات الوظيفية، الوظائف، الموظفين — بما فيهم تبويبات &quot;الشركات&quot; (إدارة) و&quot;الدرجات&quot; (وظيفة).</li><li>مستخدم بلا منحة لـ Application محمي بيترفض (<code>404</code>) من صفحة القائمة والعرض الاتنين.</li></ul><h2 id="helpers-الاختبارات-اللي-يستاهل-تعرفها" tabindex="-1">Helpers الاختبارات اللي يستاهل تعرفها <a class="header-anchor" href="#helpers-الاختبارات-اللي-يستاهل-تعرفها" aria-label="Permalink to &quot;Helpers الاختبارات اللي يستاهل تعرفها&quot;">​</a></h2><p>معرّفين في <code>OrganizationScopeTest.php</code>، ومستخدمين عبر باقي ملفات Organization الثلاثة عن طريق تعريف Pest للدوال العامة:</p><ul><li><code>makeOrgTree()</code> — بيبني A (شركة أم) ← B ← C، كل واحدة بفرع رئيسي، وسلسلة إدارة مالية←رواتب متصلة بـ A.</li><li><code>makeEmployeeUser(array $attributes)</code> — <code>Employee</code> مربوط بـ <code>User</code> حقيقي.</li><li><code>plantEmployee(array $attributes)</code> — <code>Employee</code> بلا <code>User</code> (فيكسچر &quot;زميل&quot;). الاتنين بيملّوا تلقائيًا لقب/درجة وظيفية متماسكة مع <code>department_id</code> المُمرّر لو المستدعي مقدمش واحدة، عشان الفيكسچرز تعدّي <code>Employee::assertOrganizationallyConsistent()</code> (فرع↔كيان، لقب↔إدارة، درجة↔لقب) بلا ما كل موقع استدعاء يبني السلسلة دي يدويًا.</li></ul>',19)])])}const m=t(r,[["render",n]]);export{h as __pageData,m as default};
